query GetProduct($id: ID!) {
  product(id: $id) {
    id
    name
    price { amountMinor currency }
    priceBeforeMarkdown { amountMinor currency }
    availability
  }
}

query BrowseProducts($first: Int!, $after: String) {
  products(first: $first, after: $after, sort: PRICE_ASC) {
    edges { cursor node { id name price { amountMinor currency } } }
    pageInfo { hasNextPage endCursor }
    totalCount
  }
}

query ReadCart($id: ID!) {
  cart(id: $id) {
    id status customerId
    items { id productId quantity unitPrice { amountMinor currency } product { name } }
    total { amountMinor currency }
  }
}

query ReadOrder($id: ID!) {
  order(id: $id) {
    id status createdAt
    items { productId name quantity unitPrice { amountMinor currency } }
    total { amountMinor currency }
    shipments { id status trackingCode }
  }
}

query MyOrders($first: Int!, $after: String) {
  orders(first: $first, after: $after) {
    edges { cursor node { id status total { amountMinor currency } } }
    pageInfo { hasNextPage endCursor }
    totalCount
  }
}

mutation CreateProduct($input: CreateProductInput!) {
  createProduct(input: $input) {
    product { id name sku price { amountMinor currency } availability categoryId sellerId }
  }
}

mutation UpdateProduct($id: ID!, $input: UpdateProductInput!) {
  updateProduct(id: $id, input: $input) {
    product { id name priceBeforeMarkdown { amountMinor currency } }
  }
}

mutation AddItem($input: AddCartItemInput!) {
  addCartItem(input: $input) {
    cart { id status items { id productId quantity } total { amountMinor currency } }
  }
}

mutation UpdateItem($input: UpdateCartItemInput!) {
  updateCartItem(input: $input) {
    cart { id items { id productId quantity } total { amountMinor currency } }
  }
}

mutation RemoveItem($cartId: ID!, $itemId: ID!) {
  removeCartItem(cartId: $cartId, itemId: $itemId) {
    cart { id items { id productId quantity } total { amountMinor currency } }
  }
}

mutation PlaceOrder($input: CreateOrderInput!) {
  createOrder(input: $input) {
    order { id status total { amountMinor currency } items { productId name quantity } }
    replayed
  }
}

mutation CancelOrder($id: ID!, $reason: String) {
  cancelOrder(id: $id, reason: $reason) { order { id status } }
}

mutation Review($input: AddReviewInput!) {
  addReview(input: $input) { review { id productId rating comment createdAt } }
}

mutation ReturnOrder($input: CreateReturnInput!) {
  createReturn(input: $input) { returnRequest { id orderId reason status createdAt } }
}

query PublicAndPrivate {
  product(id: "prod_1001") { id name }
  me { id name }
}

query ProductCard($showOriginal: Boolean!) {
  product(id: "prod_1001") {
    name
    price { amountMinor currency }
    priceBeforeMarkdown @include(if: $showOriginal) { amountMinor currency }
  }
}

query Compare($first: ID!, $second: ID!) {
  first: product(id: $first) { id name price { amountMinor currency } }
  second: product(id: $second) { id name price { amountMinor currency } }
}
